window.AUTH=window.AUTH||{};window.AUTH["17-778"]={"d":"17-778","id":"2018/17-778","n":"Quarles v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Jamar Quarles","date":"2019-02-20","url":"https://www.supremecourt.gov/DocketPDF/17/17-778/88986/20190220174626532_Quarles%20Opening%20Brief%20-%20to%20Printer.pdf","side":"pet","n":109},{"k":"respondent","label":"Brief of respondent United States","date":"2019-03-22","url":"https://www.supremecourt.gov/DocketPDF/17/17-778/92906/20190322151203474_17-778%20Quarles.pdf","side":"res","n":64},{"k":"reply","label":"Reply of petitioner Jamar Quarles","date":"2019-04-15","url":"https://www.supremecourt.gov/DocketPDF/17/17-778/96469/20190415133125838_2019-04-15%20Quarles%20Reply%20Brief%20-%20to%20Printer.pdf","side":"pet","n":33}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-778_7li8.pdf","tr":true,"items":[{"t":"case","label":"Adamo Wrecking Co. v. United States","cite":"434 U.S. 275","y":1978,"id":"1977/76-911","sc":1,"by":{"0":"29"}},{"t":"case","label":"Begay v. United States","cite":"553 U.S. 137","y":2008,"id":"2007/06-11543","sc":1,"by":{"0":"passim","2":"21"},"q":[{"src":"brief","b":0,"text":"use [a] gun deliberately to harm a victim.","cite":"553 U.S. 137, 145"},{"src":"brief","b":0,"text":"deliberately point [a] gun and pull the trigger.","cite":"553 U.S. 137, 146"}]},{"t":"case","label":"Bifulco v. United States","cite":"447 U.S. 381","y":1980,"id":"1979/79-5010","sc":1,"by":{"0":"29"}},{"t":"case","label":"Bonds v. State","cite":"436 N.E.2d 295","y":1982,"court":"Ind.","url":"https://www.courtlistener.com/c/N.E.2d/436/295/","by":{"0":"35"}},{"t":"case","label":"Braddy v. State","cite":"111 So. 3d 810","y":2012,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%203d/111/810/","by":{"0":"47","1":"24, 37"},"q":[{"src":"argument","who":"Mr. Tripp","text":"The domestic violence one, Braddy versus -- out of Florida. You know -- and a lot of these are very, very serious crimes. And I think they illustrate that what these people are engaged in is very erratic and impulsive decision-making, right, that they've -- they -- they already decided to break into somebody's house, and then they make an impulsive -- or -- or to be in a place where they're not supposed to be and not leave, and then they make a decision to -- to engage in some other further conduct, I think in many cases is really very, very serious."}]},{"t":"case","label":"Champlin v. State","cite":"267 N.W.2d 295","y":1978,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W.2d/267/295/","by":{"0":"46"}},{"t":"case","label":"Commonwealth v. Gonzales","cite":"443 A.2d 301","y":1982,"court":"Pa. Super. Ct.","url":"https://www.courtlistener.com/c/A.2d/443/301/","by":{"0":"43"},"q":[{"src":"brief","b":0,"text":"to be convicted of burglary, the defendant must have formed the intent to commit a crime when he entered * * * , not after he entered.","cite":"443 A.2d 301, 304"}]},{"t":"case","label":"Commonwealth v. Russell","cite":"460 A.2d 316","y":1983,"court":"Pa. Super. Ct.","url":"https://www.courtlistener.com/c/A.2d/460/316/","by":{"0":"43"},"q":[{"src":"brief","b":0,"text":"to be convicted of burglary, the defendant must have formed the intent to commit a crime when he entered * * * , not after he entered.","cite":"460 A.2d 316, 321"}]},{"t":"case","label":"Commonwealth v. Vinnicombe","cite":"549 N.E.2d 1137","y":1990,"court":"Mass. App. Ct.","url":"https://www.courtlistener.com/c/N.E.2d/549/1137/","by":{"0":"37"}},{"t":"case","label":"Cooper v. People","cite":"973 P.2d 1234","y":1999,"court":"Colo.","url":"https://www.courtlistener.com/c/P.2d/973/1234/","by":{"0":"31, 32","1":"37","2":"11, 14"},"q":[{"src":"brief","b":0,"text":"coexist with the initial point of unlawful entry or remaining.","cite":"973 P.2d 1234, 1240"}]},{"t":"case","label":"Davis v. State","cite":"611 So. 2d 906","y":1992,"court":"Miss.","url":"https://www.courtlistener.com/c/So.%202d/611/906/","by":{"0":"38"}},{"t":"case","label":"Day v. State","cite":"532 S.W.2d 302","y":1976,"court":"Tex. Crim. App.","url":"https://www.courtlistener.com/c/S.W.2d/532/302/","by":{"0":"48"}},{"t":"case","label":"Delgado v. State","cite":"776 So. 2d 233","y":2000,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%202d/776/233/","by":{"0":"47","1":"36"},"q":[{"src":"brief","b":0,"text":"ma[de] his remaining in the premises after the withdrawal [of consent] a burglary.","cite":"776 So. 2d 233"}]},{"t":"case","label":"Dolan v. State","cite":"925 A.2d 495","y":2007,"court":"Del.","url":"https://www.courtlistener.com/c/A.2d/925/495/","by":{"0":"29, 32","1":"37"}},{"t":"case","label":"Espinoza v. State","cite":"955 S.W.2d 108","y":1997,"court":"Tex. App.","url":"https://www.courtlistener.com/c/S.W.2d/955/108/","by":{"0":"48"}},{"t":"case","label":"Garcia v. State","cite":"463 N.E.2d 1099","y":1984,"court":"Ind.","url":"https://www.courtlistener.com/c/N.E.2d/463/1099/","by":{"0":"35"}},{"t":"case","label":"Gratton v. State","cite":"456 So. 2d 865","y":1984,"court":"Ala. Crim. App.","url":"https://www.courtlistener.com/c/So.%202d/456/865/","by":{"0":"46","1":"22"},"q":[{"src":"brief","b":0,"text":"formed after the entry and while the accused remains unlawfully.","cite":"456 So. 2d 865, 872"},{"src":"argument","who":"Mr. Tripp","text":"These are the facts of Gratton out of Alabama, of DeNoyer out of South Dakota, of Fontes out of Ohio. That's -- that's the seeing a woman after you break in."}]},{"t":"case","label":"Griego v. People","cite":"19 P.3d 1","y":2001,"court":"Colo.","url":"https://www.courtlistener.com/c/P.3d/19/1/","by":{"0":"31"},"q":[{"src":"brief","b":0,"text":"coexist with the initial point of unlawful entry or remaining.","cite":"19 P.3d 1"}]},{"t":"case","label":"Harper v. State","cite":"478 So. 2d 1017","y":1985,"court":"Miss.","url":"https://www.courtlistener.com/c/So.%202d/478/1017/","by":{"0":"38"}},{"t":"case","label":"Hewatt v. State","cite":"455 S.E.2d 104","y":1995,"court":"Ga. Ct. App.","url":"https://www.courtlistener.com/c/S.E.2d/455/104/","by":{"0":"47"}},{"t":"case","label":"Hickerson v. State","cite":"667 S.W.2d 654","y":1984,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W.2d/667/654/","by":{"0":"31","1":"35","2":"13"}},{"t":"case","label":"Johnson v. United States","cite":"135 S. Ct. 2551","y":2015,"id":"2014/13-7120","sc":1,"by":{"0":"10, 30","1":"2, 4"}},{"t":"case","label":"Jones v. Commonwealth","cite":"687 S.E.2d 738","y":2010,"court":"Va.","url":"https://www.courtlistener.com/c/S.E.2d/687/738/","by":{"0":"45"}},{"t":"case","label":"Jones v. United States","cite":"526 U.S. 227","y":1999,"id":"1998/97-6203","sc":1,"by":{"0":"8"}},{"t":"case","label":"Keith v. State","cite":"225 S.E.2d 719","y":1976,"court":"Ga. Ct. App.","url":"https://www.courtlistener.com/c/S.E.2d/225/719/","by":{"0":"47","1":"22"}},{"t":"case","label":"Lawson v. Commonwealth","cite":"53 S.W.3d 534","y":2001,"court":"Ky.","url":"https://www.courtlistener.com/c/S.W.3d/53/534/","by":{"0":"49"},"q":[{"src":"brief","b":0,"text":"subsequently form[] the intent necessary to be guilty of the crime of burglary.","cite":"53 S.W.3d 534"}]},{"t":"case","label":"Levesque v. State","cite":"217 N.W.2d 317","y":1974,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W.2d/217/317/","by":{"0":"45, 46"},"q":[{"src":"brief","b":0,"text":"include[] the idea of presence within","cite":"217 N.W.2d 317, 318"}]},{"t":"case","label":"Mathis v. United States","cite":"136 S. Ct. 2243","y":2016,"id":"2015/15-6092","sc":1,"by":{"0":"6, 7, 17","1":"39, 40","2":"17"},"q":[{"src":"brief","b":0,"text":"focus[es] solely on whether the elements of the crime of conviction sufficiently match the elements of generic burglary, while ignoring the particular facts of the case.","cite":"136 S. Ct. 2243, 2248"},{"src":"brief","b":0,"text":"a good rule of thumb for reading [this Court’s] decisions is that what they say and what they mean are one and the same.","cite":"136 S. Ct. at 2254"},{"src":"argument","who":"Mr. Marwell","text":"Even if so, I think under this Court -- the way this Court said in Shepard and Mathis, the kinds of facts that are available to the sentencing judge, those are limited to ones where the defendant confirmed the accuracy."}]},{"t":"case","label":"Matthews v. State","cite":"741 P.2d 370","y":1987,"court":"Idaho Ct. App.","url":"https://www.courtlistener.com/c/P.2d/741/370/","by":{"0":"33"}},{"t":"case","label":"McCarthy v. Commonwealth","cite":"867 S.W.2d 469","y":1993,"court":"Ky.","url":"https://www.courtlistener.com/c/S.W.2d/867/469/","by":{"0":"49"},"q":[{"src":"brief","b":0,"text":"subsequently form[] the intent necessary to be guilty of the crime of burglary.","cite":"867 S.W.2d 469, 471"}]},{"t":"case","label":"McClellan v. Commonwealth","cite":"715 S.W.2d 464","y":1986,"court":"Ky.","url":"https://www.courtlistener.com/c/S.W.2d/715/464/","by":{"0":"49"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"by":{"0":"25"}},{"t":"case","label":"People v. Barnhart","cite":"638 P.2d 814","y":1981,"court":"Colo. App.","url":"https://www.courtlistener.com/c/P.2d/638/814/","by":{"0":"31","1":"35"},"q":[{"src":"brief","b":0,"text":"coexist with the initial point of unlawful entry or remaining.","cite":"638 P.2d 814, 816"}]},{"t":"case","label":"People v. Barron","cite":"163 N.W.2d 219","y":1968,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W.2d/163/219/","by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"entertained at the time a felonious intent.","cite":"163 N.W.2d 219, 221"}]},{"t":"case","label":"People v. Bondurant","cite":"296 P.3d 200","y":2012,"court":"Colo. App.","url":"https://www.courtlistener.com/c/P.3d/296/200/","by":{"0":"31"},"q":[{"src":"brief","b":0,"text":"legislatively overruled Cooper with respect to the intent element of burglary.","cite":"296 P.3d 200, 214"}]},{"t":"case","label":"People v. Boose","cite":"487 N.E.2d 1088","y":1985,"court":"Ill. App. Ct.","url":"https://www.courtlistener.com/c/N.E.2d/487/1088/","by":{"0":"34","1":"22, 36"}},{"t":"case","label":"People v. Bradford","cite":"50 N.E.3d 1112","y":2016,"court":"Ill.","url":"https://www.courtlistener.com/c/N.E.3d/50/1112/","by":{"0":"34","1":"22"},"q":[{"src":"brief","b":0,"text":"burglary by remaining includes situations in which an individual enters a public building lawfully, but, in order to commit a theft or felony, (1) hides and waits for the building to close, (2) enters unauthorized areas within the building, or (3) continues to remain on the premises after his authority is explicitly revoked.","cite":"50 N.E.3d 1112, 1120"}]},{"t":"case","label":"People v. Cash","cite":"351 N.W.2d 822","y":1984,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W.2d/351/822/","by":{"0":"9"}},{"t":"case","label":"People v. Gaines","cite":"546 N.E.2d 913","y":1989,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/546/913/","by":{"0":"passim","1":"24, 36, 37","2":"3, 4, 14, 15"},"q":[{"src":"brief","b":0,"text":"A defendant who simply trespasses with no intent to commit a crime inside a building does not possess the more culpable mental state that justifies punishment as a burglar.","cite":"546 N.E.2d at 915"},{"src":"brief","b":0,"text":"should have been instructed that they must find defendant’s intent to commit a crime in the building existed at the time of the entry, or whether no such instruction need have been given, because the ‘remains unlawfully’ element of the statute means that such intent may be formed after defendant’s unlawful entry.","cite":"546 N.E.2d at 914"},{"src":"argument","who":"Mr. Marwell","text":"And you look at the fact patterns of the cases that are really the point of disagreement between us and the government, you know, Gaines from the New York Court of Appeals, a homeless person who breaks into a warehouse to get out of the cold, while he's in there decides to grab a jacket and is caught coming out, or the case of young people who break into a house not -- not intending to steal something -- this is the JNS case from Oregon -- take something while they're in there and caught on the way out."},{"src":"argument","who":"Mr. Tripp","text":"It's true there is some that are much more minor like -- like Gaines, the facts of that. But, again, what makes that sympathetic is not the timing; it's the -- it's a homeless guy who's cold, right?"}]},{"t":"case","label":"People v. Green","cite":"404 N.E.2d 930","y":1980,"court":"Ill. App. Ct.","url":"https://www.courtlistener.com/c/N.E.2d/404/930/","by":{"0":"34","1":"36","2":"13"},"q":[{"src":"brief","b":0,"text":"aimed at a situation where a defendant lawfully enters a building and then conceals himself with the intent to commit a felony.","cite":"404 N.E.2d 930, 932"}]},{"t":"case","label":"People v. Tackett","cite":"414 N.E.2d 748","y":1980,"court":"Ill. App. Ct.","url":"https://www.courtlistener.com/c/N.E.2d/414/748/","by":{"0":"34"}},{"t":"case","label":"People v. Weaver","cite":"243 N.E.2d 245","y":1968,"court":"Ill.","url":"https://www.courtlistener.com/c/N.E.2d/243/245/","by":{"0":"34, 35","1":"35"},"q":[{"src":"brief","b":0,"text":"[a] criminal intent formulated after a lawful entry will not satisfy the statute.","cite":"243 N.E.2d 245, 248"}]},{"t":"case","label":"Ray v. State","cite":"522 So. 2d 963","y":1988,"court":"Fla. Dist. Ct. App.","url":"https://www.courtlistener.com/c/So.%202d/522/963/","by":{"0":"47"},"q":[{"src":"brief","b":0,"text":"ma[de] his remaining in the premises after the withdrawal [of consent] a burglary.","cite":"522 So. 2d 963, 966-967"}]},{"t":"case","label":"Reed v. State","cite":"560 A.2d 1104","y":1989,"court":"Md.","url":"https://www.courtlistener.com/c/A.2d/560/1104/","by":{"0":"36"}},{"t":"case","label":"Scott v. Commonwealth","cite":"323 S.E.2d 572","y":1984,"court":"Va.","url":"https://www.courtlistener.com/c/S.E.2d/323/572/","by":{"0":"45"}},{"t":"case","label":"Sessions v. Dimaya","cite":"138 S. Ct. 1204","y":2018,"id":"2017/15-1498","sc":1,"by":{"0":"30"}},{"t":"case","label":"Shepard v. United States","cite":"544 U.S. 13","y":2005,"id":"2004/03-9168","sc":1,"by":{"0":"8"},"q":[{"src":"brief","b":0,"text":"the charging 1 Although Quarles argued below that his conviction under Mich. Comp. Law § 750.110a(4) does not constitute a conviction for generic burglary under the modified categorical approach, neither the district court nor the Sixth Circuit had occasion to reach the issue, having resolved his challenge on the threshold question presented here. document, the terms of a plea agreement or transcript of colloquy between judge and defendant in which the factual basis for the plea was confirmed by the defendant, or to some comparable judicial record of this information.","cite":"544 U.S. 13, 26"},{"src":"argument","who":"Mr. Marwell","text":"Even if so, I think under this Court -- the way this Court said in Shepard and Mathis, the kinds of facts that are available to the sentencing judge, those are limited to ones where the defendant confirmed the accuracy."}]},{"t":"case","label":"Shetters v. State","cite":"751 P.2d 31","y":1988,"court":"Alaska Ct. App.","url":"https://www.courtlistener.com/c/P.2d/751/31/","by":{"0":"30","1":"24","2":"12, 14"}},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"by":{"0":"30"}},{"t":"case","label":"State v. Adams","cite":"581 P.2d 868","y":1978,"court":"Nev.","url":"https://www.courtlistener.com/c/P.2d/581/868/","by":{"0":"40"}},{"t":"case","label":"State v. Allen","cite":"110 P.3d 849","y":2005,"court":"Wash. Ct. App.","url":"https://www.courtlistener.com/c/P.3d/110/849/","by":{"0":"49","1":"24"}},{"t":"case","label":"State v. Arne","cite":"311 N.W.2d 186","y":1981,"court":"N.D.","url":"https://www.courtlistener.com/c/N.W.2d/311/186/","by":{"0":"42","1":"36"}},{"t":"case","label":"State v. Belcher","cite":"776 P.2d 811","y":1989,"court":"Ariz. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/776/811/","by":{"0":"46"}},{"t":"case","label":"State v. Belton","cite":"461 A.2d 973","y":1983,"court":"Conn.","url":"https://www.courtlistener.com/c/A.2d/461/973/","by":{"0":"32","1":"36","2":"13"},"q":[{"src":"argument","who":"Mr. Marwell","text":"There are states like Alaska, which has the Arabie decision from 1985; New York, which has the Licata decision from 1971; Connecticut, which has the Belton decision from 1983, where the court said that \"remaining in\" applies to a lawful entry followed by a subsequent formation of intent."}]},{"t":"case","label":"State v. Burdette","cite":"611 N.W.2d 615","y":2000,"court":"Neb.","url":"https://www.courtlistener.com/c/N.W.2d/611/615/","by":{"0":"40"}},{"t":"case","label":"State v. Cosby","cite":"321 N.W.2d 365","y":1982,"court":"Wis. Ct. App.","url":"https://www.courtlistener.com/c/N.W.2d/321/365/","by":{"0":"46"},"q":[{"src":"brief","b":0,"text":"if he did not form the requisite intent to steal until he awoke inside the tavern, the offense of theft, not burglary, was committed because the intent to steal was not formed prior to or at the time of entry.","cite":"321 N.W.2d 365"}]},{"t":"case","label":"State v. Courville","cite":"769 P.2d 44","y":1989,"court":"Mont.","url":"https://www.courtlistener.com/c/P.2d/769/44/","by":{"0":"39"}},{"t":"case","label":"State v. DeNoyer","cite":"541 N.W.2d 725","y":1995,"court":"S.D.","url":"https://www.courtlistener.com/c/N.W.2d/541/725/","by":{"0":"48","1":"22"},"q":[{"src":"brief","b":0,"text":"the person remain[s] in the structure after forming the intent to commit a crime.","cite":"541 N.W.2d 725, 732"},{"src":"argument","who":"Mr. Tripp","text":"These are the facts of Gratton out of Alabama, of DeNoyer out of South Dakota, of Fontes out of Ohio. That's -- that's the seeing a woman after you break in."}]},{"t":"case","label":"State v. Dible","cite":"538 N.W.2d 267","y":1995,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W.2d/538/267/","by":{"0":"47"}},{"t":"case","label":"State v. Edwards","cite":"524 A.2d 648","y":1987,"court":"Conn. App. Ct.","url":"https://www.courtlistener.com/c/A.2d/524/648/","by":{"0":"32","1":"36"}},{"t":"case","label":"State v. Embree","cite":"633 P.2d 1057","y":1981,"court":"Ariz. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/633/1057/","by":{"0":"46","1":"22"}},{"t":"case","label":"State v. Field","cite":"379 A.2d 393","y":1977,"court":"Me.","url":"https://www.courtlistener.com/c/A.2d/379/393/","by":{"0":"35","1":"35","2":"13"},"q":[{"src":"brief","b":0,"text":"an essential element of burglary * * * that at the time defendant makes an unauthorized entry into a building defendant must then entertain actual intent to commit a specific crime","cite":"379 A.2d 393, 395"}]},{"t":"case","label":"State v. Flowers","cite":"475 N.E.2d 790","y":1984,"court":"Ohio Ct. App.","url":"https://www.courtlistener.com/c/N.E.2d/475/790/","by":{"0":"50","1":"22"}},{"t":"case","label":"State v. Fontes","cite":"721 N.E.2d 1037","y":2000,"court":"Ohio","url":"https://www.courtlistener.com/c/N.E.2d/721/1037/","by":{"0":"50","1":"22, 37"},"q":[{"src":"argument","who":"Mr. Tripp","text":"These are the facts of Gratton out of Alabama, of DeNoyer out of South Dakota, of Fontes out of Ohio. That's -- that's the seeing a woman after you break in."}]},{"t":"case","label":"State v. Gilliland","cite":"741 S.E.2d 521","y":2012,"court":"S.C. Ct. App.","url":"https://www.courtlistener.com/c/S.E.2d/741/521/","by":{"0":"44"}},{"t":"case","label":"State v. Gutierrez","cite":"172 P.3d 18","y":2007,"court":"Kan.","url":"https://www.courtlistener.com/c/P.3d/172/18/","by":{"0":"48"}},{"t":"case","label":"State v. Hanson","cite":"2007 WL 2177334","y":2007,"court":"Minn. Ct. App. July 31","by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"[I]t is necessary that the defendant had the intent to commit that crime at the time that the defendant either entered or remained in the building. Whether the defendant intended to commit the crime must be determined from all the circumstances, including, the manner and time of entry or remaining in the building.","cite":"2007 WL 2177334"}]},{"t":"case","label":"State v. Howard","cite":"42 S.E. 173","y":1902,"court":"S.C.","url":"https://www.courtlistener.com/c/S.E./42/173/","by":{"0":"43"}},{"t":"case","label":"State v. Jennings","cite":"691 P.2d 882","y":1984,"court":"N.M. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/691/882/","by":{"0":"41"}},{"t":"case","label":"State v. Jones","cite":"426 So. 2d 1323","y":1983,"court":"La.","url":"https://www.courtlistener.com/c/So.%202d/426/1323/","by":{"0":"35, 50"}},{"t":"case","label":"State v. Mahoe","cite":"972 P.2d 287","y":1998,"court":"Haw.","url":"https://www.courtlistener.com/c/P.2d/972/287/","by":{"0":"33","1":"37"},"q":[{"src":"brief","b":0,"text":"to expand the offense of burglary to include situations in which the criminal intent develops after an unlawful entry or remaining has occurred.","cite":"972 P.2d 287, 291"}]},{"t":"case","label":"State v. Manthie","cite":"641 P.2d 454","y":1982,"court":"Mont.","url":"https://www.courtlistener.com/c/P.2d/641/454/","by":{"0":"39","1":"36"}},{"t":"case","label":"State v. McCormick","cite":"277 S.E.2d 629","y":1981,"court":"W. Va.","url":"https://www.courtlistener.com/c/S.E.2d/277/629/","by":{"0":"45"}},{"t":"case","label":"State v. McKnight","cite":"426 P.3d 669","y":2018,"court":"Or. Ct. App.","url":"https://www.courtlistener.com/c/P.3d/426/669/","by":{"0":"51"}},{"t":"case","label":"State v. Mogenson","cite":"701 P.2d 1339","y":1985,"court":"Kan. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/701/1339/","by":{"0":"48","1":"22"}},{"t":"case","label":"State v. Nelson","cite":"523 N.W.2d 667","y":1994,"court":"Minn. Ct. App.","url":"https://www.courtlistener.com/c/N.W.2d/523/667/","by":{"0":"38"},"q":[{"src":"brief","b":0,"text":"[I]t is necessary that the defendant had the intent to commit that crime at the time that the defendant either entered or remained in the building. Whether the defendant intended to commit the crime must be determined from all the circumstances, including, the manner and time of entry or remaining in the building.","cite":"523 N.W.2d 667, 669-670"}]},{"t":"case","label":"State v. Nieves, A-2010-11T4","cite":"2014 WL 886810","y":2014,"court":"N.J. Super. Ct. App. Div. Mar. 7","by":{"0":"41","2":"10"}},{"t":"case","label":"State v. O’Rourke","cite":"399 A.2d 1237","y":1979,"court":"R.I.","url":"https://www.courtlistener.com/c/A.2d/399/1237/","by":{"0":"43"}},{"t":"case","label":"State v. One 1990 Chevrolet Pickup","cite":"523 N.W.2d 389","y":1994,"court":"N.D.","url":"https://www.courtlistener.com/c/N.W.2d/523/389/","by":{"0":"42","2":"13"}},{"t":"case","label":"State v. Papineau","cite":"630 P.2d 904","y":1981,"court":"Or. App. Ct.","url":"https://www.courtlistener.com/c/P.2d/630/904/","by":{"0":"50","1":"22","2":"11"}},{"t":"case","label":"State v. Peacock","cite":"330 S.E.2d 190","y":1985,"court":"N.C.","url":"https://www.courtlistener.com/c/S.E.2d/330/190/","by":{"0":"42"}},{"t":"case","label":"State v. Pyron","cite":"495 A.2d 467","y":1985,"court":"N.J. Super. Ct. App. Div.","url":"https://www.courtlistener.com/c/A.2d/495/467/","by":{"0":"41","1":"35"}},{"t":"case","label":"State v. Reardon","cite":"431 A.2d 796","y":1981,"court":"N.H.","url":"https://www.courtlistener.com/c/A.2d/431/796/","by":{"0":"40"}},{"t":"case","label":"State v. Rollins","cite":"882 S.W.2d 314","y":1994,"url":"https://www.courtlistener.com/c/S.W.2d/882/314/","by":{"0":"39"}},{"t":"case","label":"State v. Rudolph","cite":"970 P.2d 1221","y":1998,"court":"Utah","url":"https://www.courtlistener.com/c/P.2d/970/1221/","by":{"0":"51","1":"24, 37"}},{"t":"case","label":"State v. Tellegen","cite":"314 P.3d 902","y":2013,"court":"Mont.","url":"https://www.courtlistener.com/c/P.3d/314/902/","by":{"0":"39"}},{"t":"case","label":"State v. Wesemann","cite":"1995 WL 605442","y":1995,"court":"Tenn. Crim. App. Oct. 16","by":{"0":"55"}},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"by":{"0":"passim","1":"passim","2":"passim"},"q":[{"src":"brief","b":0,"text":"basic elements of [1] unlawful or unprivileged entry into, or remaining in, [2] a building or structure, [3] with intent to commit a crime.","cite":"495 U.S. 575, 599"},{"src":"brief","b":0,"text":"the large proportion of crimes committed by a small number of career offenders, and the inadequacy of state prosecutorial resources to address this problem.","cite":"495 U.S. 575, 583"},{"src":"brief","b":1,"text":"unlawful or unprivileged entry into, or remaining in, a building or other structure, with intent to commit a crime.","cite":"495 U.S. at 598"},{"src":"brief","b":1,"text":"generic burglary, as defined in Taylor, does not require intent at entry; rather the intent can be developed while ‘remaining in.’","cite":"495 U.S. at 598"},{"src":"brief","b":2,"text":"career offenders * * * who commit a large number of fairly serious crimes as their means of livelihood.","cite":"495 U.S. at 587"},{"src":"brief","b":2,"text":"prepared to use violence if necessary to carry out his plans or to escape.","cite":"495 U.S. at 588"}]},{"t":"case","label":"United States v. Bernel-Aveja","cite":"844 F.3d 206","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/844/206/","by":{"0":"passim","2":"2, 9"}},{"t":"case","label":"United States v. Bonilla","cite":"687 F.3d 188","y":2012,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/687/188/","by":{"0":"16, 19","1":"40"},"q":[{"src":"brief","b":0,"text":"[c]ontemporaneous intent was the essence of burglary at common law, as it was the element that distinguished the offense from trespass.","cite":"687 F.3d at 196"}]},{"t":"case","label":"United States v. Granderson","cite":"511 U.S. 39","y":1994,"id":"1993/92-1662","sc":1,"by":{"0":"29","2":"23"}},{"t":"case","label":"United States v. Herrera-Montes","cite":"490 F.3d 390","y":2007,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/490/390/","by":{"0":"55"},"q":[{"src":"brief","b":0,"text":"teenagers who unlawfully enter a house only to party, and only later decide to","cite":"490 F.3d 390, 392"}]},{"t":"case","label":"United States v. Herrold","cite":"883 F.3d 517","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/883/517/","by":{"0":"17, 54","1":"28, 30","2":"passim"},"q":[{"src":"brief","b":1,"text":"does not include any ‘remaining in’ language at all.","cite":"883 F.3d 517, 533"},{"src":"brief","b":1,"text":"The timing of when intent was formed implicates neither the culpability of the perpetrator nor the extent of danger to victims.","cite":"883 F.3d at 547"},{"src":"brief","b":2,"text":"sole example of [‘remaining in’] burglary describe[d] ‘a bank customer who hides in the bank until it closes and then takes the bank’s money.’","cite":"883 F.3d at 532"},{"src":"brief","b":2,"text":"To speak of problems of proof associated with possible intent formation ‘after the unlawful . . . remaining’ would be incoherent otherwise—the only way intent can form after ‘remaining’ in the [continuous] sense would be if it formed after the defendant totally left the premises.","cite":"883 F.3d at 533"}]},{"t":"case","label":"United States v. McArthur","cite":"850 F.3d 925","y":2017,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/850/925/","by":{"0":"16, 23","2":"1, 4"},"q":[{"src":"brief","b":0,"text":"requires intent to commit a crime at the time of the unlawful or unprivileged entry or the initial ‘remaining in’ without consent.","cite":"850 F.3d 925, 939"},{"src":"brief","b":0,"text":"it is a discrete event that occurs at the moment when a perpetrator, who at one point was lawfully present, exceeds his license and overstays his welcome.","cite":"850 F.3d at 939"}]},{"t":"case","label":"United States v. Priddy","cite":"808 F.3d 676","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/808/676/","by":{"0":"11","1":"7","2":"17"},"q":[{"src":"brief","b":0,"text":"someone who enters a building or structure and, while inside, commits or attempts to commit a felony will necessarily have remained inside the building or structure to do so.","cite":"808 F.3d 676, 685"},{"src":"brief","b":1,"text":"someone who enters a building or structure and, while inside, commits or attempts to commit a felony will necessarily have remained inside the building or structure to do so.","cite":"808 F.3d 676, 685"},{"src":"argument","who":"Mr. Marwell","text":"We cited in our brief the Priddy case from the Sixth Circuit. Tennessee is one of the statutes. The Priddy case decided that Tennessee was divisible."}]},{"t":"case","label":"United States v. Richards","cite":"2014 WL 6686783","y":2014,"court":"D. Neb. Nov. 26","by":{"0":"40"}},{"t":"case","label":"United States v. Stitt","cite":"139 S. Ct. 399","y":2018,"id":"2018/17-765","sc":1,"by":{"0":"2, 14, 26","1":"16"},"q":[{"src":"brief","b":1,"text":"‘the generic sense in which the term was used in the criminal codes of most States.’","cite":"139 S. Ct. at 406"},{"src":"brief","b":1,"text":"viewed burglary as an inherently dangerous crime,","cite":"139 S. Ct. at 406"},{"src":"argument","who":"Justice Gorsuch","text":"We had some conversation last term in Stitt and Sims about how we approach these cases generally. And I guess I'm wondering whether the government's given any further thought to that?"}]},{"t":"case","label":"Van Cannon v. United States","cite":"890 F.3d 656","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/890/656/","by":{"0":"16, 19","2":"1, 2, 9"}},{"t":"case","label":"Worchester v. State","cite":"536 P.2d 995","y":1975,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P.2d/536/995/","by":{"0":"43"},"q":[{"src":"brief","b":0,"text":"have the requisite criminal intent at the time of unlawful entry.","cite":"536 P.2d 995, 998"}]},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)","(g)(1)","(g)(9)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"by":{"0":"1, 4, 8","1":"3, 2, 3, 25"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(a)(2)","(e)","(e)(1)","(e)(2)(B)","(e)(2)(B)(ii)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"by":{"0":"4, 4, 6, 1, 5, 1","1":"3, 19, 26, 19, 26"},"q":[{"src":"brief","b":0,"text":"violent felony or * * * serious drug offense.","cite":"18 U.S.C. § 924(e)(1)"},{"src":"brief","b":1,"text":"or otherwise involves conduct that presents a serious potential risk of physical injury to another","cite":"18 U.S.C. 924(e)(2)(B)(ii)"}]},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1837","by":{"0":"4, 15, 17"}},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"0":"5"}},{"t":"case","label":"Arabie v. State","cite":"699 P.2d 890","y":1985,"court":"Alaska Ct. App.","url":"https://www.courtlistener.com/c/P.2d/699/890/","by":{"1":"36","2":"12"},"q":[{"src":"argument","who":"Mr. Marwell","text":"There are states like Alaska, which has the Arabie decision from 1985; New York, which has the Licata decision from 1971; Connecticut, which has the Belton decision from 1983, where the court said that \"remaining in\" applies to a lawful entry followed by a subsequent formation of intent."}]},{"t":"case","label":"Entick v. Carrington","cite":"95 Eng. Rep. 807","y":1765,"court":"K.B.","url":"https://www.courtlistener.com/c/Eng.%20Rep./95/807/","by":{"1":"17"}},{"t":"case","label":"Forest Grove Sch. Dist. v. T. A.","cite":"557 U.S. 230","y":2009,"id":"2008/08-305","sc":1,"by":{"1":"26"}},{"t":"case","label":"Graham Cnty. Soil & Water Conservation Dist. v. United States ex rel. Wilson","cite":"559 U.S. 280","y":2010,"id":"2009/08-304","sc":1,"by":{"1":"15"}},{"t":"case","label":"James v. United States","cite":"550 U.S. 192","y":2007,"id":"2006/05-9264","sc":1,"by":{"1":"29, 31, 32"},"q":[{"src":"brief","b":1,"text":"The main risk of burglary arises * * * from the possibility of a face-to-face confrontation between the burglar and a third party— whether an occupant, a police officer, or a bystander— who comes to investigate.","cite":"550 U.S. at 203"}]},{"t":"case","label":"People v. Johnson","cite":"284 N.W.2d 718","y":1979,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W.2d/284/718/","by":{"1":"40"}},{"t":"case","label":"People v. Vallero","cite":"378 N.E.2d 549","y":1978,"court":"Ill. App. Ct.","url":"https://www.courtlistener.com/c/N.E.2d/378/549/","by":{"1":"22"}},{"t":"case","label":"Smith v. United States","cite":"877 F.3d 720","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/877/720/","by":{"1":"16"},"q":[{"src":"brief","b":1,"text":"a compact version of standards found in many states’ criminal codes,","cite":"877 F.3d 720, 725"}]},{"t":"case","label":"Sparre v. State","cite":"164 So. 3d 1183","y":2015,"url":"https://www.courtlistener.com/c/So.%203d/164/1183/","by":{"1":"36"}},{"t":"case","label":"State v. Jones","cite":"440 N.E.2d 580","y":1981,"court":"Ohio Ct. App.","url":"https://www.courtlistener.com/c/N.E.2d/440/580/","by":{"1":"22"}},{"t":"case","label":"State v. Walker","cite":"600 N.W.2d 606","y":1999,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W.2d/600/606/","by":{"1":"24"}},{"t":"case","label":"Stokeling v. United States","cite":"139 S. Ct. 544","y":2019,"id":"2018/17-5554","sc":1,"by":{"1":"25","2":"16, 17"},"q":[{"src":"brief","b":1,"text":"ha[s] repeatedly declined to construe the statute in a way that would render it inapplicable in many States.","cite":"139 S. Ct. 544, 552"},{"src":"brief","b":2,"text":"render [ACCA’s burglary predicate] inapplicable in many States.","cite":"139 S. Ct. 544, 552"},{"src":"argument","who":"Mr. Marwell","text":"But we think this Court's decision in Castleman and Stokeling looks -- when it asks the question of how many jurisdictions would be excluded, is looking to the time that Congress adopted the statute."},{"src":"argument","who":"Mr. Marwell","text":"So I don't -- so, again, I think the -- the relevant question is how many would have been knocked out at the time Congress enacted ACCA, since that, I think, is the fairest reading of Castleman and Stokeling."}]},{"t":"case","label":"Sullivan v. Stroop","cite":"496 U.S. 478","y":1990,"id":"1989/89-535","sc":1,"by":{"1":"18"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"by":{"1":"25","2":"16"},"q":[{"src":"argument","who":"Mr. Marwell","text":"But we think this Court's decision in Castleman and Stokeling looks -- when it asks the question of how many jurisdictions would be excluded, is looking to the time that Congress adopted the statute."},{"src":"argument","who":"Mr. Marwell","text":"So I don't -- so, again, I think the -- the relevant question is how many would have been knocked out at the time Congress enacted ACCA, since that, I think, is the fairest reading of Castleman and Stokeling."}]},{"t":"case","label":"United States v. Cores","cite":"356 U.S. 405","y":1958,"id":"1957/455","sc":1,"by":{"1":"7, 14, 15, 26, 38","2":"6, 7"},"q":[{"src":"brief","b":1,"text":"permits no connotation other than continuing presence.","cite":"356 U.S. 405, 408"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"the crucial word ‘remains’ permits no connotation other than continuing presence.","cite":"356 U. S., at 408"},{"src":"argument","who":"Mr. Tripp","text":"That's what this Court already held in Cores, the case about the alien crewman who remained in the United States unlawfully because he was still here."}]},{"t":"case","label":"United States v. Jones","cite":"565 U.S. 400","y":2012,"id":"2011/10-1259","sc":1,"by":{"1":"17"}},{"t":"case","label":"Welch v. United States","cite":"136 S. Ct. 1257","y":2016,"id":"2015/15-6418","sc":1,"by":{"1":"4"}},{"t":"case","label":"Young v. State","cite":"266 S.W.3d 744","y":2007,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W.3d/266/744/","by":{"1":"35, 36","2":"13"}},{"t":"usc","label":"8 U.S.C. § 1282","url":"https://www.law.cornell.edu/uscode/text/8/1282","subs":["(c)(1952)"],"by":{"1":"14"}},{"t":"usc","label":"18 U.S.C. § 1752","url":"https://www.law.cornell.edu/uscode/text/18/1752","subs":["(a)(1982)","(a)(1)"],"stext":{"head":"§1752. Restricted building or grounds","paras":[[0,"(a) Whoever—"],[1,"(1) knowingly enters or remains in any restricted building or grounds without lawful authority to do so;"],[1,"(2) knowingly, and with intent to impede or disrupt the orderly conduct of Government business or official functions, engages in disorderly or disruptive conduct in, or within such proximity to, any restricted building or grounds when, or so that, such conduct, in fact, impedes or disrupts the orderly conduct of Government business or official functions;"],[1,"(3) knowingly, and with the intent to impede or disrupt the orderly conduct of Government business or official functions, obstructs or impedes ingress or egress to or from any restricted building or grounds; or 1"],[1,"(4) knowingly engages in any act of physical violence against any person or property in any restricted building or grounds; 2"],[1,"(5) knowingly and willfully operates an unmanned aircraft system with the intent to knowingly and willfully direct or otherwise cause such unmanned aircraft system to enter or operate within or above a restricted building or grounds;"],[0,"or attempts or conspires to do so, shall be punished as provided in subsection (b)."],[0,"(b) The punishment for a violation of subsection (a) is—"],[1,"(1) a fine under this title or imprisonment for not more than 10 years, or both, if—"],[2,"(A) the person, during and in relation to the offense, uses or carries a deadly or dangerous weapon or firearm; or"],[2,"(B) the offense results in significant bodily injury as defined by section 2118(e)(3); and"],[1,"(2) a fine under this title or imprisonment for not more than one year, or both, in any other case."],[0,"(c) In this section—"],[1,"(1) the term \"restricted buildings or grounds\" means any posted, cordoned off, or otherwise restricted area—"],[2,"(A) of the White House or its grounds, or the Vice President's official residence or its grounds;"],[2,"(B) of a building or grounds where the President or other person protected by the Secret Service is or will be temporarily visiting; or"],[2,"(C) of a building or grounds so restricted in conjunction with an event designated as a special event of national significance; and"],[1,"(2) the term \"other person protected by the Secret Service\" means any person whom the United States Secret Service is authorized to protect under section 3056 of this title or by Presidential memorandum, when such person has not declined such protection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1752?type=usc&year=mostrecent&link-type=html"},"by":{"1":"21, 15","2":"7"}},{"t":"usc","label":"18 U.S.C. § 2118","url":"https://www.law.cornell.edu/uscode/text/18/2118","subs":["(b)"],"stext":{"head":"§2118. Robberies and burglaries involving controlled substances","paras":[[0,"(a) Whoever takes or attempts to take from the person or presence of another by force or violence or by intimidation any material or compound containing any quantity of a controlled substance belonging to or in the care, custody, control, or possession of a person registered with the Drug Enforcement Administration under section 302 of the Controlled Substances Act (21 U.S.C. 822) shall, except as provided in subsection (c), be fined under this title or imprisoned not more than twenty years, or both, if (1) the replacement cost of the material or compound to the registrant was not less than $500, (2) the person who engaged in such taking or attempted such taking traveled in interstate or foreign commerce or used any facility in interstate or foreign commerce to facilitate such taking or attempt, or (3) another person was killed or suffered significant bodily injury as a result of such taking or attempt."],[0,"(b) Whoever, without authority, enters or attempts to enter, or remains in, the business premises or property of a person registered with the Drug Enforcement Administration under section 302 of the Controlled Substances Act (21 U.S.C. 822) with the intent to steal any material or compound containing any quantity of a controlled substance shall, except as provided in subsection (c), be fined under this title or imprisoned not more than twenty years, or both, if (1) the replacement cost of the controlled substance to the registrant was not less than $500, (2) the person who engaged in such entry or attempted such entry or who remained in such premises or property traveled in interstate or foreign commerce or used any facility in interstate or foreign commerce to facilitate such entry or attempt or to facilitate remaining in such premises or property, or (3) another person was killed or suffered significant bodily injury as a result of such entry or attempt."],[0,"(c)(1) Whoever in committing any offense under subsection (a) or (b) assaults any person, or puts in jeopardy the life of any person, by the use of a dangerous weapon or device shall be fined under this title and imprisoned for not more than twenty-five years."],[0,"(2) Whoever in committing any offense under subsection (a) or (b) kills any person shall be fined under this title or imprisoned for any term of years or life, or both."],[0,"(d) If two or more persons conspire to violate subsection (a) or (b) of this section and one or more of such persons do any overt act to effect the object of the conspiracy, each shall be fined under this title or imprisoned not more than ten years or both."],[0,"(e) For purposes of this section—"],[1,"(1) the term \"controlled substance\" has the meaning prescribed for that term by section 102 of the Controlled Substances Act;"],[1,"(2) the term \"business premises or property\" includes conveyances and storage facilities; and"],[1,"(3) the term \"significant bodily injury\" means bodily injury which involves a risk of death, significant physical pain, protracted and obvious disfigurement, or a protracted loss or impairment of the function of a bodily member, organ, or mental or sensory faculty."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2118?type=usc&year=mostrecent&link-type=html"},"by":{"1":"21","2":"7"}},{"t":"case","label":"Bullock v. BankChampaign, N.A.","cite":"569 U.S. 267","y":2013,"id":"2012/11-1518","sc":1,"by":{"2":"5"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"by":{"2":"5"}},{"t":"case","label":"Esquivel-Quintana v. Sessions","cite":"137 S. Ct. 1562","y":2017,"id":"2016/16-54","sc":1,"by":{"2":"17"}},{"t":"case","label":"Neal v. Clark","cite":"95 U.S. 704","y":1877,"id":"scdb/1877-139","sc":1,"by":{"2":"4, 5"},"q":[{"src":"argument","who":"Mr. Marwell","text":"Well, I -- the -- this Court in the Neal case that we cited in our reply brief has said when you have a pair of words, you know, disjunctive pair of words, you look at one in the context of the other."}]},{"t":"case","label":"People v. Licata","cite":"268 N.E.2d 787","y":1971,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/268/787/","by":{"2":"14, 15"},"q":[{"src":"argument","who":"Mr. Marwell","text":"There are states like Alaska, which has the Arabie decision from 1985; New York, which has the Licata decision from 1971; Connecticut, which has the Belton decision from 1983, where the court said that \"remaining in\" applies to a lawful entry followed by a subsequent formation of intent."}]},{"t":"case","label":"State v. Richardson","cite":"2015 WL 405735","y":2015,"court":"Haw. Ct. App. Jan. 30","by":{"2":"11"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"by":{"2":"6"}}]};